// =============================================================================
// Node 2: Extract Incoming Message & Match Client Organization
// =============================================================================
const body = $input.first().json.body || $input.first().json;

const fromNumber = body.From || '';
const toNumber = body.To || '';
const messageBody = body.Body || '';
const messageSid = body.MessageSid || `SM_${Date.now()}`;

// Match Client Organization based on Twilio Destination Number ('To')
let orgId = '00000000-0000-0000-0000-000000000001';
let orgName = 'Northside Plumbing & Heating';

const auditLog = `[BRIK INCOMING SMS] Client: ${orgName} (${orgId}) | From Customer: ${fromNumber} | Message: "${messageBody}"`;
console.log(auditLog);

// Prepare Database Payloads for Supabase
const customerRecord = {
  organization_id: orgId,
  name: `Customer ${fromNumber.slice(-4)}`,
  phone: fromNumber,
  source: 'SMS Reply',
  updated_at: new Date().toISOString()
};

const messageRecord = {
  organization_id: orgId,
  from_number: fromNumber,
  to_number: toNumber,
  message_body: messageBody,
  message_type: 'INBOUND_REPLY',
  direction: 'INBOUND',
  status: 'RECEIVED',
  twilio_message_sid: messageSid,
  timestamp: new Date().toISOString()
};

return [{
  json: {
    success: true,
    action: 'incoming_sms_stored',
    organization_id: orgId,
    organization_name: orgName,
    from_number: fromNumber,
    to_number: toNumber,
    message_body: messageBody,
    message_sid: messageSid,
    audit_log: auditLog,
    supabase_payloads: {
      customer: customerRecord,
      message: messageRecord
    }
  }
}];
